guesses = [64, 97, 80, 88, 92, 90, 89, 91]
responses = ["higher", "lower", "higher", "higher", "lower", "lower", "higher", "lower"]

def likelihood(secret, guesses, responses):
    """Compute likelihood of responses given secret number"""
    p = 1.0
    for guess, response in zip(guesses, responses):
        if guess == secret:
            # Must return "equals"
            if response == "equals":
                # Correct, probability 1 (deterministic)
                pass
            else:
                # This shouldn't happen - probability 0
                return 0.0
        elif guess < secret:
            true_response = "higher"
        else:  # guess > secret
            true_response = "lower"

        if response == true_response:
            p *= 0.7  # Correct response
        else:
            p *= 0.3  # Noisy/flipped response
    return p

