    l = likelihood(n, guesses, responses)
    if l > 0:
        candidates.append((n, l))

# Sort by likelihood descending
candidates.sort(key=lambda x: -x[1])

print("Top candidates:")
for n, l in candidates[:10]:
    print(f"  {n}: {l:.6f}")
