#!/usr/bin/env python3
import json
import subprocess
import os

def load_log():
    if os.path.exists("/agent/guess_log.json"):
        with open("/agent/guess_log.json") as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": 8}

def make_guess(n):
    result = subprocess.run(["./guess.py", str(n)], capture_output=True, text=True)
    print(result.stdout)
    if result.returncode != 0:
        print(result.stderr)
    return load_log()

def update_beliefs(beliefs, guess, response):
    """Update beliefs based on the response."""
    new_beliefs = {}

    for x in range(1, 129):
        if response == "equals":
            if x == guess:
                new_beliefs[x] = 1.0
            else:
                new_beliefs[x] = 0.0
        else:
            # Calculate likelihood
            if x > guess:
                # true_response would be "higher"
                if response == "higher":
                    likelihood = 0.7
                else:  # "lower"
                    likelihood = 0.3
            elif x < guess:
                # true_response would be "lower"
                if response == "lower":
                    likelihood = 0.7
                else:  # "higher"
                    likelihood = 0.3
            else:  # x == guess
                # Should get "equals", got something else
                likelihood = 0.0  # or very small?

            new_beliefs[x] = beliefs[x] * likelihood

    # Normalize
    total = sum(new_beliefs.values())
    if total > 0:
        for x in new_beliefs:
            new_beliefs[x] /= total

    return new_beliefs

def get_weighted_median(beliefs):
    """Get the weighted median of the belief distribution."""
    sorted_items = sorted(beliefs.items(), key=lambda x: x[0])
    cumulative = 0
    for x, p in sorted_items:
        cumulative += p
        if cumulative >= 0.5:
            return x
    return sorted_items[-1][0]

def main():
    # Initialize uniform beliefs
    beliefs = {x: 1/128 for x in range(1, 129)}

    log = load_log()
    guesses_made = len(log["guesses"])
    guesses_remaining = log["guesses_remaining"]

    print(f"Starting with {guesses_remaining} guesses remaining, {guesses_made} already made")

    # If we have previous guesses, rebuild beliefs
    if guesses_made > 0:
        # Reset to uniform and re-apply
        beliefs = {x: 1/128 for x in range(1, 129)}
        for g, r in zip(log["guesses"], log["responses"]):
            beliefs = update_beliefs(beliefs, g, r)

    for i in range(guesses_remaining):
        if guesses_remaining - i <= 0:
            break

        # Find the best guess - weighted median
        guess = get_weighted_median(beliefs)
        print(f"\nQuery {i+1}: Guessing {guess}")

        log = make_guess(guess)
        response = log["responses"][-1]
        print(f"Response: {response}")

        beliefs = update_beliefs(beliefs, guess, response)

        # Check if we found it
        if response == "equals":
            print(f"Found it! The secret number is {guess}")
            return guess

        # Show top candidates
        sorted_beliefs = sorted(beliefs.items(), key=lambda x: -x[1])
        print(f"Top 5 candidates: {sorted_beliefs[:5]}")

    # Return most likely candidate
    best = max(beliefs.items(), key=lambda x: x[1])
    print(f"\nMost likely answer: {best[0]} (probability {best[1]:.4f})")
    return best[0]

if __name__ == "__main__":
    answer = main()
    print(f"\nFinal answer: {answer}")
