#!/usr/bin/env python3
import json
import subprocess
import os

def load_log():
    if os.path.exists("/agent/guess_log.json"):
        with open("/agent/guess_log.json") as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": 8}

def make_guess(n):
    result = subprocess.run(["./guess.py", str(n)], capture_output=True, text=True)
    output = result.stdout.strip()
    print(output)
    return load_log(), output

def likelihood(guess, response, secret):
    """Compute likelihood of observing 'response' when comparing 'guess' to 'secret'."""
    if guess == secret:
        return 1.0 if response == "equals" else 0.0
    elif guess < secret:
        # True response should be "higher"
        return 0.7 if response == "higher" else 0.3
    else:  # guess > secret
        # True response should be "lower"
        return 0.7 if response == "lower" else 0.3

def score_candidate(secret, guesses, responses):
    """Compute log-likelihood of 'secret' being the answer given all queries."""
    log_likelihood = 0
    for g, r in zip(guesses, responses):
        ll = likelihood(g, r, secret)
        if ll == 0:
