            expected = "higher"
        elif guess > T:
            expected = "lower"
        else:
            expected = "equals"

        if response == expected:
            if expected == "equals":
                # Equals is always correct (no noise)
                log_likelihood += 0  # prob = 1
            else:
                log_likelihood += 0  # Using counts, not log for simplicity
                # Actually let's use probability
    # Let me redo with actual probabilities
    prob = 1.0
    for guess, response in zip(guesses, responses):
        if guess < T:
            expected = "higher"
        elif guess > T:
            expected = "lower"
        else:
            expected = "equals"

        if expected == "equals":
            if response == "equals":
                prob *= 1.0
            else:
                prob = 0  # Impossible
                break
        else:
            if response == expected:
                prob *= (1 - noise_prob)  # 0.7
            else:
                prob *= noise_prob  # 0.3

    if prob > 0:
        print(f"T={T}: prob={prob:.6f}")

