#!/usr/bin/env python3
import json
import os
import subprocess
import sys

GUESS_LOG = "/agent/guess_log.json"

def load_log():
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    return {"guesses": [], "responses": [], "guesses_remaining": 8}

def make_guess(guess_num):
    result = subprocess.run(["./guess.py", str(guess_num)], capture_output=True, text=True)
    print(result.stdout.strip())
    if result.stderr:
        print(result.stderr.strip(), file=sys.stderr)
    return load_log()

def get_median(probs):
    """Get the median of the probability distribution."""
    cumulative = 0
    for i, p in enumerate(probs, 1):
        cumulative += p
        if cumulative >= 0.5:
            return i
    return len(probs)

def update_probs(probs, guess, response):
    """Update probability distribution based on response."""
    noise = 0.3
    new_probs = probs.copy()

    if response == "equals":
        # If equals, that value is very likely correct
        # But even "equals" could be noisy... actually looking at the code, 
        # noise only applies to non-equal responses
        return [0 if i != guess else 1 for i in range(1, 129)]

    if response == "higher":
        # Secret > guess (with 70% probability), or Secret < guess (with 30% probability)
        for i in range(1, 129):
            if i > guess:
                # If secret > guess, response should be "higher" (correct with prob 0.7)
                new_probs[i-1] *= 0.7
            elif i < guess:
                # If secret < guess, response should be "lower" but we got "higher" (wrong with prob 0.3)
                new_probs[i-1] *= 0.3
    elif response == "lower":
        # Secret < guess (with 70% probability), or Secret > guess (with 30% probability)
        for i in range(1, 129):
            if i < guess:
                # If secret < guess, response should be "lower" (correct with prob 0.7)
                new_probs[i-1] *= 0.7
            elif i > guess:
                # If secret > guess, response should be "higher" but we got "lower" (wrong with prob 0.3)
                new_probs[i-1] *= 0.3

    # Normalize
    total = sum(new_probs)
    if total > 0:
        new_probs = [p / total for p in new_probs]

    return new_probs

def main():
    # Initialize uniform distribution
    probs = [1.0/128] * 128

    log = load_log()

    for step in range(8):
        if log["guesses_remaining"] <= 0:
            break

        # Check if we already got "equals"
        if log["responses"] and log["responses"][-1] == "equals":
            print(f"Found it! Answer is {log['guesses'][-1]}")
            break

        # Get median guess
        guess = get_median(probs)
        print(f"Step {step+1}: Guessing {guess} (range: {[i+1 for i, p in enumerate(probs) if p > 0.001][:5]}...{[i+1 for i, p in enumerate(probs) if p > 0.001][-5:]})")

        # Make guess
        log = make_guess(guess)

        if log["responses"][-1] == "equals":
            print(f"Confirmed! Answer is {guess}")
            break

        # Update probabilities
        probs = update_probs(probs, guess, log["responses"][-1])

        # Show top candidates
        indexed = [(probs[i], i+1) for i in range(128)]
        indexed.sort(reverse=True)
        print(f"Top 5: {indexed[:5]}")
        print(f"Remaining guesses: {log['guesses_remaining']}")
        print()

    # Final answer is the most probable
    best_idx = probs.index(max(probs))
    print(f"Final answer: {best_idx + 1}")

if __name__ == "__main__":
    main()
