python3 << 'EOF'
guesses = [64, 96, 112, 120, 124, 122, 121]
responses = ["higher", "higher", "higher", "higher", "lower", "lower", "lower"]
noise_prob = 0.3

def likelihood(T):
    prob = 1.0
    for g, r in zip(guesses, responses):
        if g == T:
            # Should have returned "equals"
            if r == "equals":
                continue  # prob *= 1
            else:
                return 0  # Impossible
        elif g < T:
            # True response should be "higher"
            if r == "higher":
                prob *= (1 - noise_prob)  # 0.7
            else:
                prob *= noise_prob  # 0.3
        else:  # g > T
            # True response should be "lower"
            if r == "lower":
                prob *= (1 - noise_prob)  # 0.7
            else:
                prob *= noise_prob  # 0.3
    return prob

# Find the target with highest likelihood
best_T = -1
best_prob = -1
for T in range(1, 129):
    p = likelihood(T)
    if p > best_prob:
        best_prob = p
        best_T = T

print(f"Most likely target: {best_T} with likelihood {best_prob}")

# Also print top 10
results = [(T, likelihood(T)) for T in range(1, 129)]
results.sort(key=lambda x: x[1], reverse=True)
print("\nTop 10 candidates:")
for T, p in results[:10]:
    print(f"  T={T}: {p}")
EOF

