guesses = [64, 96, 112, 120, 116, 118, 117, 119]
responses = ["higher", "higher", "higher", "lower", "higher", "lower", "higher", "lower"]

def score(n):
    if n in guesses:
        return 0  # Can't be a guessed number (would have returned "equals")
    s = 1.0
    for g, r in zip(guesses, responses):
        if r == "higher":
            if n > g:
                s *= 0.7
