# Check all targets 1-128 for consistency with responses
# Exclude targets where guess == target but response != 'equals'
guesses = [64, 96, 80, 88, 92, 90, 89]
responses = ['higher', 'lower', 'higher', 'higher', 'lower', 'lower', 'lower']

best_targets = []
min_flips = 999

for target in range(1, 129):
    flips = 0
    valid = True
    for guess, response in zip(guesses, responses):
        if guess == target:
            if response != 'equals':
                valid = False
                break
        elif guess < target:
            expected = 'higher'
        elif guess > target:
            expected = 'lower'
        else:
            expected = 'equals'

        if expected != 'equals':
            if response != expected:
                flips += 1

    if valid:
        if flips < min_flips:
            min_flips = flips
            best_targets = [target]
        elif flips == min_flips:
            best_targets.append(target)

print(f'Minimum flips: {min_flips}')
print(f'Best targets: {best_targets}')
"

